#!/usr/bin/env python3
"""Write src/gbk_table.h: GBK (CP936) double-byte characters to Unicode.

The hook decodes GBK cheat names from usrcheat.dat with this table. It is
embedded because the MLP1 has no iconv GBK module to call instead.

    python3 tools/gen_gbk_table.py > src/gbk_table.h
"""

import sys

LEAD_FIRST, LEAD_LAST = 0x81, 0xFE
TRAIL_FIRST, TRAIL_LAST = 0x40, 0xFE
PER_LINE = 16


def main():
    out = sys.stdout
    out.write(
        "/* Generated by tools/gen_gbk_table.py from Python's gbk codec. Do not edit.\n"
        "   gbk_ucs[lead - 0x81][trail - 0x40] is the Unicode codepoint of a GBK\n"
        "   double-byte character, or 0 where the pair is unassigned (trail 0x7F\n"
        "   is never valid). Every assigned pair maps into the BMP. */\n"
        "#include <stdint.h>\n"
        "\n"
        "#define GBK_LEAD_FIRST  0x%02X\n"
        "#define GBK_LEAD_LAST   0x%02X\n"
        "#define GBK_TRAIL_FIRST 0x%02X\n"
        "#define GBK_TRAIL_LAST  0x%02X\n"
        "static const uint16_t gbk_ucs[%d][%d] = {\n"
        % (LEAD_FIRST, LEAD_LAST, TRAIL_FIRST, TRAIL_LAST,
           LEAD_LAST - LEAD_FIRST + 1, TRAIL_LAST - TRAIL_FIRST + 1))
    for lead in range(LEAD_FIRST, LEAD_LAST + 1):
        row = []
        for trail in range(TRAIL_FIRST, TRAIL_LAST + 1):
            try:
                ch = bytes([lead, trail]).decode("gbk")
            except UnicodeDecodeError:
                row.append(0)
                continue
            if len(ch) != 1 or ord(ch) > 0xFFFF:
                sys.exit("unexpected mapping for %02X %02X" % (lead, trail))
            row.append(ord(ch))
        out.write("    { /* 0x%02X */\n" % lead)
        for i in range(0, len(row), PER_LINE):
            out.write("        " + ",".join(str(v) for v in row[i:i + PER_LINE]) + ",\n")
        out.write("    },\n")
    out.write("};\n")


if __name__ == "__main__":
    main()
